import{_ as n,y as d,a as i,o as h,g as t,D as s,a2 as r,I as o}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/dashboard.md","filePath":"getting-started/dashboard.md","lastUpdated":1789441803000}'),l={name:"getting-started/dashboard.md"};function g(c,e,p,u,m,T){const a=d("ImagePopup");return h(),i("div",null,[e[3]||(e[3]=t("h1",{id:"dashboard",tabindex:"-1"},[o("Dashboard "),t("a",{class:"header-anchor",href:"#dashboard","aria-label":'Permalink to "Dashboard"'},"​")],-1)),e[4]||(e[4]=t("p",null,"The dashboard is the first page you see after you sign in. It sums up your store's sales, orders and customers for a period, lists today's orders, shows the products with the least stock, and ranks your best-selling products and customers.",-1)),e[5]||(e[5]=t("p",null,[o("To come back to it, click "),t("strong",null,"Dashboard"),o(" in the sidebar or the logo in the header.")],-1)),s(a,{src:"/images/getting-started/dashboard.png",alt:"Dashboard with Overall Details, Today’s Details and Store Stats for the last 30 days"}),e[6]||(e[6]=r('<p>The page opens with a greeting that uses your name.</p><p>On a new store, most figures are 0 until the first orders are placed. <strong>Stock Threshold</strong> shows <em>There is no product available</em> until products have stock entered, <strong>Top Selling Products</strong> shows <em>Add related products on the go.</em> until an order in the period is invoiced, and <strong>Customer With Most Sales</strong> shows <em>No Customer Found With Most Sales</em> until the period has an order.</p><h2 id="choose-the-period-and-channel" tabindex="-1">Choose the period and channel <a class="header-anchor" href="#choose-the-period-and-channel" aria-label="Permalink to &quot;Choose the period and channel&quot;">​</a></h2><p>The dashboard opens on the last 30 days. To look at another period:</p>',4)),t("ol",null,[e[1]||(e[1]=t("li",null,[t("p",null,"Click the date range at the top right.")],-1)),t("li",null,[e[0]||(e[0]=r("<p>Choose a preset, such as <strong>Today</strong>, <strong>This Week</strong>, <strong>Last 30 Days</strong> or <strong>This Year</strong>, or click the first and last day of the period on the calendar. <strong>Start Date</strong> and <strong>End Date</strong> under the calendar show your choice. You can&#39;t pick a day in the future.</p>",1)),s(a,{src:"/images/getting-started/dashboard-date-range.png",alt:"Date range picker on the dashboard with its presets and calendar"})]),e[2]||(e[2]=t("li",null,[t("p",null,[o("If your store has more than one channel, choose a channel in the list beside the date range, or "),t("strong",null,"All Channels"),o(".")])],-1))]),e[7]||(e[7]=r('<p>Every card reloads. The channel applies to every card except <strong>Total Unpaid Invoices</strong>. The period doesn&#39;t change <strong>Today’s Details</strong> or <strong>Stock Threshold</strong>.</p><h3 id="how-the-figures-are-counted" tabindex="-1">How the figures are counted <a class="header-anchor" href="#how-the-figures-are-counted" aria-label="Permalink to &quot;How the figures are counted&quot;">​</a></h3><ul><li><strong>Sales</strong> are what has been invoiced minus what has been refunded, in your store&#39;s base currency. They&#39;re counted on the day the order was placed, even when it was invoiced later. An order that hasn&#39;t been invoiced yet counts as an order but adds nothing to sales.</li><li><strong>Orders</strong> are all orders placed in the period, whatever their status, including canceled ones.</li><li>The percentage under a figure compares it with the same number of days before the period starts. For example, with <strong>Last 30 Days</strong> selected, it compares with the 30 days before that. A green arrow means the figure went up, a red arrow that it went down.</li><li>With <strong>Today</strong> or <strong>Yesterday</strong> selected, the percentage isn&#39;t a useful comparison. To compare today with yesterday, use <strong>Today’s Details</strong>.</li></ul><h2 id="overall-details" tabindex="-1">Overall Details <a class="header-anchor" href="#overall-details" aria-label="Permalink to &quot;Overall Details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Total Sales</strong></td><td>Sales in the period.</td></tr><tr><td><strong>Total Orders</strong></td><td>Orders placed in the period.</td></tr><tr><td><strong>Total Customers</strong></td><td>Customers who created an account in the period.</td></tr><tr><td><strong>Average Order Sale</strong></td><td>The average sale per order in the period. Orders that aren&#39;t invoiced yet count as 0.</td></tr><tr><td><strong>Total Unpaid Invoices</strong></td><td>The total of invoices in the <strong>Pending</strong> state, for all channels and dates. It has no percentage.</td></tr></tbody></table><p>To follow up on unpaid invoices, see <a href="./../orders/create-invoice.html">Create Invoice</a>.</p><h2 id="today-s-details" tabindex="-1">Today’s Details <a class="header-anchor" href="#today-s-details" aria-label="Permalink to &quot;Today’s Details&quot;">​</a></h2><p><strong>Today’s Sales</strong>, <strong>Today’s Orders</strong> and <strong>Today’s Customers</strong> show today&#39;s figures so far, compared with the whole of yesterday.</p><p>Below them, every order placed today is listed with the date and time it was placed, its status, total, payment method and channel, the customer&#39;s name and email, the billing city and country, and pictures of up to three items with a tile counting the rest. Click the arrow on an order to open it.</p><h2 id="stock-threshold" tabindex="-1">Stock Threshold <a class="header-anchor" href="#stock-threshold" aria-label="Permalink to &quot;Stock Threshold&quot;">​</a></h2><p><strong>Stock Threshold</strong> lists the five products with the least stock, lowest first, with each product&#39;s picture, name, SKU, price and quantity. Stock is counted per inventory source, so a product kept at two sources can appear twice.</p>',11)),s(a,{src:"/images/getting-started/dashboard-stock-threshold.png",alt:"Stock Threshold card listing five products with their SKU, price and stock"}),e[8]||(e[8]=r('<p>The quantity is green when it&#39;s above the <strong>Out-of-Stock Threshold</strong> set under <a href="./../configure/back-orders.html">Configure &gt;&gt; Catalog &gt;&gt; Inventory</a>, and red when it&#39;s at or below it. Click the arrow on a product to edit it and add stock.</p><h2 id="store-stats" tabindex="-1">Store Stats <a class="header-anchor" href="#store-stats" aria-label="Permalink to &quot;Store Stats&quot;">​</a></h2><p>The right-hand <strong>Store Stats</strong> card has three sections, each showing the period it covers.</p><ul><li><strong>Total Sales</strong>: your sales and number of orders, with a graph of sales over the period. The graph shows a bar per day, per week for longer periods, and per month for periods longer than five months.</li><li><strong>Top Selling Products</strong>: the five products with the most sales in the period, with the price each sold at and its sales: the item totals invoiced minus refunded, before discounts and without tax or shipping. Click a product to edit it.</li><li><strong>Customer With Most Sales</strong>: the five customers with the most sales in the period, with their name, email address, total sales and number of orders. Guest shoppers are included. A customer whose orders aren&#39;t invoiced yet is listed with a total of 0. Click a registered customer to open their account.</li></ul><h2 id="who-can-see-the-dashboard" tabindex="-1">Who can see the dashboard <a class="header-anchor" href="#who-can-see-the-dashboard" aria-label="Permalink to &quot;Who can see the dashboard&quot;">​</a></h2><p>The dashboard needs the <strong>Dashboard</strong> permission in the user&#39;s <a href="./../settings/roles.html">role</a>. A user whose role doesn&#39;t have it goes straight to the first page their role allows when they sign in, and <strong>Dashboard</strong> isn&#39;t shown in their sidebar.</p><p>For more detailed figures, such as sales by payment method or customers by group, see <a href="./../reporting/sales-report.html">Reporting</a>.</p>',7))])}const w=n(l,[["render",g]]);export{f as __pageData,w as default};
